def lpHaarLevelProjection (𝕜 : Type*) [RCLike 𝕜] (p : BanachExponent) (n : ℕ) :
    IntervalLp 𝕜 p →L[𝕜] IntervalLp 𝕜 p :=
  ∑ k : Fin (2 ^ n), (lpHaarDyadicCoefficient 𝕜 p n k).smulRight (lpHaarDyadic 𝕜 p n k)

